import java.io.DataInputStream;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        int n = readInt(dis);
        int answer = new Solver().calculate(n);
        System.out.print(answer);
    }

    static class Solver {
        int mod = 1000000007;

        int calculate(int n) throws IOException {
            int size = 2 * n + 1;
            int[][][] dp = new int[size][size][2];
            dp[0][0][0] = 1;
            for (int depth = 1; depth <= 2 * n; depth++) {
                for (int opened = depth & 1; opened <= depth; opened += 2) {
                    if (opened - 1 >= 0) {
                        dp[depth][opened][0] += dp[depth - 1][opened - 1][1];
                        dp[depth][opened][1] += dp[depth - 1][opened - 1][0];
                    }
                    if (opened + 1 < size) {
                        dp[depth][opened][0] += dp[depth - 1][opened + 1][1];
                        dp[depth][opened][1] += dp[depth - 1][opened + 1][0];
                    }
                    dp[depth][opened][0]++;
                    dp[depth][opened][0] %= mod;
                    dp[depth][opened][1] %= mod;
                }
            }
            return dp[2 * n][0][1];
        }

        static int readInt(DataInputStream dis) throws IOException {
            int ret = 0;
            byte c;
            do {
                c = dis.readByte();
            } while (c <= ' ');
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = dis.readByte();
            }
            do {
                ret = ret * 10 + c - '0';
                c = dis.readByte();
            } while (c > ' ');
            return neg ? -ret : ret;
        }
    }
}
